 1	public final class ModularExponentiation {
 2	    private ModularExponentiation() {
 3	    }
 4	
 5	    public static int modPow(int base, int exponent, int modulus) {
 6	        validateExponent(exponent);
 7	        validateModulus(modulus);
 8	
 9	        int normalizedBase = normalizeBase(base, modulus);
10	        return compute(normalizedBase, exponent, modulus);
11	    }
12	
13	    private static int compute(int base, int exponent, int modulus) {
14	        int remainingExponent = exponent;
15	        long result = 1 % modulus;
16	
17	        while (remainingExponent > 0) {
18	            if ((remainingExponent & 1) != 0) {
19	                result = multiplyMod(result, base, modulus);
20	            }
21	
22	            base = multiplyMod(base, base, modulus);
23	            remainingExponent >>= 1;
24	        }
25	
26	        return (int) result;
27	    }
28	
29	    private static int normalizeBase(int base, int modulus) {
30	        int normalizedBase = base % modulus;
31	        if (normalizedBase < 0) {
32	            normalizedBase += modulus;
33	        }
34	        return normalizedBase;
35	    }
36	
37	    private static int multiplyMod(long left, long right, int modulus) {
38	        return (int) ((left * right) % modulus);
39	    }
40	
41	    private static void validateExponent(int exponent) {
42	        if (exponent < 0) {
43	            throw new IllegalArgumentException("Exponent must be non-negative.");
44	        }
45	    }
46	
47	    private static void validateModulus(int modulus) {
48	        if (modulus <= 0) {
49	            throw new IllegalArgumentException("Modulus must be positive.");
50	        }
51	    }
52	}

 1	public final class ModularExponentiation {
 2	    private ModularExponentiation() {
 3	    }
 4	
 5	    public static int modPow(int base, int exponent, int modulus) {
 6	        return compute(ExponentiationContext.create(base, exponent, modulus));
 7	    }
 8	
 9	    private static int compute(ExponentiationContext context) {
10	        int factor = context.normalizedBase();
11	        int remainingExponent = context.exponent();
12	        int modulus = context.modulus();
13	        long result = 1 % modulus;
14	
15	        while (remainingExponent > 0) {
16	            if ((remainingExponent & 1) != 0) {
17	                result = multiplyMod(result, factor, modulus);
18	            }
19	
20	            factor = multiplyMod(factor, factor, modulus);
21	            remainingExponent >>= 1;
22	        }
23	
24	        return (int) result;
25	    }
26	
27	    private static int normalizeBase(int base, int modulus) {
28	        int normalizedBase = base % modulus;
29	        if (normalizedBase < 0) {
30	            normalizedBase += modulus;
31	        }
32	        return normalizedBase;
33	    }
34	
35	    private static int multiplyMod(long left, long right, int modulus) {
36	        return (int) ((left * right) % modulus);
37	    }
38	
39	    private record ExponentiationContext(int normalizedBase, int exponent, int modulus) {
40	        private static ExponentiationContext create(int base, int exponent, int modulus) {
41	            if (exponent < 0) {
42	                throw new IllegalArgumentException("Exponent must be non-negative.");
43	            }
44	
45	            if (modulus <= 0) {
46	                throw new IllegalArgumentException("Modulus must be positive.");
47	            }
48	
49	            return new ExponentiationContext(normalizeBase(base, modulus), exponent, modulus);
50	        }
51	    }
52	}

